const input = $input.first().json;
const body = input.body || input;
const projectId = String(body.project_id || '').replace(/[^a-zA-Z0-9_-]/g, '');
const subPath = String(body.path || '').replace(/\.\./g, '').replace(/^\//,'');
const fileName = String(body.file || '').replace(/\.\./g, '').replace(/[\/]/g, '').replace(/[^a-zA-Z0-9._-]/g, '_');

if (!projectId || !subPath || !fileName) {
  throw new Error('project_id, path en file zijn verplicht.');
}

const basePath = '/home/node/n8n-files/projects';
const fullPath = `${basePath}/${projectId}/${subPath}/${fileName}`;

return [{ json: { fullPath, fileName } }];

const result = $input.first().json;
const fileName = $('Build Path').first().json.fileName;
const success = (result.stdout || '').trim() === 'OK';

return [{
  json: {
    success,
    message: success ? `${fileName} verwijderd.` : 'Fout bij verwijderen.'
  }
}];
